WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_m_ratio'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '工程与比例', 'kp-eng-m-ratio', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "工程与比例综合"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不给明确的天数，全篇只给比例关系。将工程量拆解为纯粹的份数游戏。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目中充斥着“甲的工作量是乙的 2/3”、“三人完成的比例为 3:4:5”等字眼。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当题目不求具体的绝对天数，只求比例或倍数时，直接【把工作量比例当成真实工作量】。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[遇到纯比例描述的工程题] --> B[直接赋予工程量具体的份数值(如W甲=3, W乙=4)]\nB --> C[根据题干其他条件找出或设定时间比例]\nC --> D[利用 P = W / T 倒推出各自的效率比]\nD --> E[用得出的效率比解决题目最终的问题]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲乙完成的工程量之比为 3:2，他们花费的时间之比为 4:5。求甲乙的效率之比？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "直接赋值工作量：W甲 = 3，W乙 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "直接赋值时间：T甲 = 4，T乙 = 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求各自效率：P甲 = 3/4，P乙 = 2/5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "化简比例：(3/4) : (2/5) = 15 : 8。答案即为 15:8。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "非要设未知数 x：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "在纯比例题中设 x, y 是多此一举，在最后相除时一定会被约掉。干脆一开始就不要让它们出现。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "训练比例的交叉相乘化简法。看到 (a/b) : (c/d)，立马写出 ad : bc。"}]}]}$$ AS jsonb), NULL, '工程与比例的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "工程与比例"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_m_ratio", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
